const brJ=city=>{const q=norm(city);if(!q)return null;if(typeof PAL_CITY_J==='object'&&PAL_CITY_J[q]&&PAL_CITY_J[q]!=='freeport')return PAL_CITY_J[q];const P=typeof navPlaces==='function'?navPlaces():[];const hit=P.find(p=>norm(p.n)===q)||P.find(p=>norm(p.n).startsWith(q))||P.find(p=>norm(p.n).includes(q));if(hit)return hit.j;const ck=typeof wdRouteKey==='function'?wdRouteKey(city):null;if(ck&&typeof PAL_CITY_J==='object'&&PAL_CITY_J[norm(ck)])return PAL_CITY_J[norm(ck)];return null;};
const brCity=city=>{const raw=String(city||'').trim();if(!raw)return '';const ck=typeof wdRouteKey==='function'?wdRouteKey(raw):null;if(ck)return ck;const q=norm(raw);const key=typeof CITY_LL==='object'?Object.keys(CITY_LL).find(k=>norm(k)===q):null;if(key)return key;const ck2=typeof wdRouteKey==='function'?wdRouteKey(raw.replace(/\b\w/g,c=>c.toUpperCase())):null;return ck2||raw.replace(/\b\w/g,c=>c.toUpperCase());};
