const brFirst=(t,n)=>{t=String(t||'');const m=t.match(/^.{20,}?[.;](\s|$)/);let out=m?m[0].trim():t;if(out.length>n){out=out.slice(0,n).replace(/\s+\S*$/,'')+'…';}return out;};
