/* the brief: the fields the form holds and the Ask parses */
const briefs=Object.assign({who:'collector',where:'Singapore',task:'buy',from:'New York',to:'',artist:'',cat:'Post-War & Contemporary',kind:'painting',year:1990,sum:2500000,party:'clean',years:7,risk:'mid'},(()=>{const s=store.get('brief',null);return s&&typeof s==='object'?s:{};})());
