  const at=cities.filter(c=>c[0]==='in'||c[0]==='at'),from=cities.filter(c=>c[0]==='from'),to=cities.filter(c=>/to$/.test(c[0])||c[0]==='into');
  if(at[0])b.where=brCity(at[0][1]);if(b.task==='sell'){if(from[0])b.from=brCity(from[0][1]);if(at[1])b.to=brCity(at[1][1]);else if(to[0])b.to=brCity(to[0][1]);}else{if(from[0])b.from=brCity(from[0][1]);else if(at[1])b.from=brCity(at[1][1]);if(to[0])b.to=brCity(to[0][1]);else if(at[2])b.to=brCity(at[2][1]);}
  if(/\b(home|back home|my home|bring it home|get it back)\b/.test(low)&&b.where&&!b.to)b.to=b.where;
  const arts=typeof palArtist==='function'?ARTISTS.map(a=>[a,norm(a).split(' ').pop().replace(/[^a-z0-9']/g,'')]).filter(([a,s])=>s.length>3&&new RegExp(`\\b${s}\\b`).test(low)):[];const full=arts.find(([a])=>low.includes(norm(a)));const art=full?full[0]:arts.length?arts.map(([a])=>[a,RESULTS.filter(r=>r.artist===a).length]).sort((x,y)=>y[1]-x[1])[0][0]:null;if(art)b.artist=art;
  const cat=BR_CATS.find(c=>low.includes(norm(c).split(' ')[0])&&!/^(post|impressionist)/.test(norm(c)))||(/\bcontemporary|post-war|postwar\b/.test(low)?'Post-War & Contemporary':/\bimpressionist|modern\b/.test(low)?'Impressionist & Modern':/\bold master/.test(low)?'Old Masters':null);if(cat)b.cat=cat;
  const kind=/\bsculpture|bronze|marble\b/.test(low)?'sculpture':/\bdrawing|print|watercolou?r|works? on paper\b/.test(low)?'paper':/\bphotograph/.test(low)?'photo':/\bdesign|chair|lamp|furniture\b/.test(low)?'design':/\bpainting|canvas|oil\b/.test(low)?'painting':null;if(kind)b.kind=kind;
  const yr=t.match(/\b(1[5-9]\d\d|20[0-2]\d)\b/);if(yr)b.year=+yr[1];
