  tides.slice(0,3).forEach(t=>{const e=(t.evidence||[])[0];out.push(`<p><span class="oc-dir ${esc(t.dir)}">${esc((OC_DIR[t.dir]||['→'])[0])}</span> <button class="lk" data-tide="${esc(t.id)}">${esc(t.n)}</button> — ${esc(OC_DIR[t.dir]?OC_DIR[t.dir][1].toLowerCase():t.dir)}, strength ${t.strength||1}/5. ${esc(t.what||'')}${e?` <span class="faint">${esc(e.fig)}${e.who?' — '+esc(e.who)+(e.when?', '+esc(e.when):''):''}.</span>`:''}</p>`);(t.src||[]).forEach(s=>S.push(s));});
