  if(T){out.push(`<p>${esc(room)} is <b>${esc(T.temp)}</b>: ${esc(T.why||T.figure||'')}${T.figure&&T.why?` <span class="faint">(${esc(T.figure)})</span>`:''}.</p>`);(T.src||[]).forEach(s=>S.push(s));}
