function renderMemo(m,opts){opts=opts||{};const b=m.b;return `<article class="br-memo${opts.cls?' '+opts.cls:''}"><header class="br-mh"><div class="br-mk">${opts.kicker||'The memo'} <span class="faint">${esc(fdate(NOW))}</span></div><h3>${esc(opts.title||briefHead(b))}</h3></header>
  ${m.parts.map(([n,p])=>`<section class="br-sec"><h4>${esc(n)}</h4>${p.html}</section>`).join('')}
  ${m.stop?`<section class="br-sec br-letter"><h4>No letter</h4><p class="br-stop">The memo stops here because ${esc(m.stop.why)}. No money is counted, no road is drawn and no letter is drafted for it: the lawful course is in the walls above, and it ends the task.</p></section>`:`<section class="br-sec br-letter"><h4>The letter, drafted</h4><pre class="br-pre">${esc(m.letter.text)}</pre><p class="faint">A draft. Nothing leaves the terminal: copy it into your own mail when you approve it. <button class="lk" data-copy="letter">Copy</button></p></section>`}
  <section class="br-sec br-srcs"><h4>Sources on this page</h4><div class="src">${brSrcs(m.src,24)||'<span class="faint">The engines’ own sources are on each tool’s page.</span>'}</div><p class="faint">A reading of the terminal’s data, composed for this brief. Not investment, legal or tax advice; a professional’s number ends every route.</p></section></article>`;}
/* the view */
function renderBrief(){const el=$('#v-brief');if(!el)return;const b=briefs;const cities=[...new Set([...(typeof PAL_CITY_J==='object'?Object.keys(PAL_CITY_J).map(c=>c.replace(/\b\w/g,x=>x.toUpperCase())):[]),...(typeof CITY_LL==='object'?Object.keys(CITY_LL):[])])].filter(c=>c.length>2).sort();
  const opt=(L,v)=>L.map(x=>`<option value="${esc(x[0])}"${x[0]===v?' selected':''}>${esc(x[1])}</option>`).join('');
  el.innerHTML=`<h1 id="h-brief">The Brief</h1><p class="lead">Say who you are, where you are and what you want. The terminal composes the case from its own engines — the reading, the money, the road, the walls, the people, the calendar, the whispers, the risks, the next steps — and drafts the letter you would send. A sentence in the Ask bar does the same: <i>I am a collector in Singapore and want to buy a Richter in New York for $3m and bring it home.</i></p>
  <form id="briefForm" class="br-form" autocomplete="off">
   <div class="br-row"><label>I am <select name="who">${opt(BR_WHO,b.who)}</select></label><label>in <input name="where" list="brCities" value="${esc(b.where)}" placeholder="a city"></label><label>and I want to <select name="task">${opt(BR_TASK,b.task)}</select></label></div>
   <div class="br-row"><label>the work: artist <input name="artist" list="brArtists" value="${esc(b.artist)}" placeholder="optional"></label><label>category <select name="cat">${BR_CATS.map(c=>`<option${c===b.cat?' selected':''}>${esc(c)}</option>`).join('')}</select></label><label>kind <select name="kind">${(typeof NAV_KINDS==='object'?NAV_KINDS:[['painting','A painting']]).map(k=>`<option value="${esc(k[0])}"${k[0]===b.kind?' selected':''}>${esc(k[1])}</option>`).join('')}</select></label><label>made in <input name="year" type="number" min="1400" max="2026" value="${esc(b.year)}"></label><label>sum <input name="sum" value="${esc(b.sum>=1e6?(b.sum/1e6)+'m':b.sum>=1e3?(b.sum/1e3)+'k':b.sum)}" placeholder="2.5m"></label></div>
   <div class="br-row"><label><span id="brFromL">the room</span> <input name="from" list="brCities" value="${esc(b.from)}" placeholder="a city"></label><label><span id="brToL">to</span> <input name="to" list="brCities" value="${esc(b.to)}" placeholder="a city (home)"></label><label>the counterparty is <select name="party">${opt(BR_PARTY,b.party)}</select></label><label>the house <select name="house">${opt(BR_HOUSES,b.house||'')}</select></label></div>
   <div class="br-row br-mats"><span class="faint">The work contains</span> ${BR_MATS.map(m=>`<label class="br-chk"><input type="checkbox" name="mats" value="${esc(m[0])}"${(b.mats||[]).includes(m[0])?' checked':''}> ${esc(m[1])}</label>`).join('')}</div>
   <div class="br-row br-opt"><label>horizon <select name="years">${[1,3,5,7,10,15,20].map(y=>`<option${+b.years===y?' selected':''}>${y}</option>`).join('')}</select> years</label><label>appetite <select name="risk">${[['low','low — keep it'],['mid','mid — lean in'],['high','high — go early']].map(r=>`<option value="${r[0]}"${b.risk===r[0]?' selected':''}>${r[1]}</option>`).join('')}</select></label><button type="submit" class="btn">Compose the memo</button><button type="button" class="lk" data-brprint="1">Save the memo as a page</button><button type="button" class="lk" data-brsave="1">Keep this brief</button></div>
   <datalist id="brCities">${cities.map(c=>`<option value="${esc(c)}">`).join('')}</datalist><datalist id="brArtists">${(typeof ARTISTS==='object'?ARTISTS:[]).slice(0,400).map(a=>`<option value="${esc(a)}">`).join('')}</datalist>
  </form>
  <div id="briefOut"></div>
  <div id="briefKept"></div>`;
  const fm=$('#briefForm',el);const read=()=>{const f=fm.elements;const sum=typeof palSum==='function'?palSum(f.sum.value):+String(f.sum.value).replace(/[^0-9.]/g,'');Object.assign(briefs,{who:f.who.value,where:f.where.value.trim(),task:f.task.value,from:f.from.value.trim(),to:f.to.value.trim(),artist:f.artist.value.trim(),cat:f.cat.value,kind:f.kind.value,year:+f.year.value||1990,sum:sum||briefs.sum,party:f.party.value,house:f.house.value||'',mats:[...fm.querySelectorAll('input[name=mats]:checked')].map(x=>x.value),years:+f.years.value||7,risk:f.risk.value});store.set('brief',briefs);};
  const labels=()=>{const t=fm.elements.task.value;const L1=$('#brFromL',el),L2=$('#brToL',el);if(L1)L1.textContent=t==='buy'?'the room':t==='sell'?'the work is in':t==='move'||t==='lend'?'from':'the work is in';if(L2)L2.textContent=t==='buy'?'home to':t==='sell'?'the room':t==='move'||t==='lend'?'to':'(unused)';};labels();fm.elements.task.addEventListener('change',labels);
  fm.addEventListener('submit',e=>{e.preventDefault();read();briefShow();});
  el.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.brprint){const o=$('#briefOut',el);if(!o||!o.firstChild){toast('Compose the memo first');return;}printable(briefHead(briefs),o);return;}
    if(t.dataset.brsave){read();const kept=store.get('briefs.kept',[]);kept.unshift({at:NOW,b:Object.assign({},briefs)});store.set('briefs.kept',kept.slice(0,12));briefKept();toast('Kept on this device');return;}
    if(t.dataset.brload!=null){const kept=store.get('briefs.kept',[]);const k=kept[+t.dataset.brload];if(k){Object.assign(briefs,k.b);store.set('brief',briefs);renderBrief();briefShow();}return;}
    if(t.dataset.brdrop!=null){const kept=store.get('briefs.kept',[]);kept.splice(+t.dataset.brdrop,1);store.set('briefs.kept',kept);briefKept();return;}
    briefClick(t);});
  briefKept();if(store.get('brief.shown',false))briefShow();}
function briefKept(){const el=$('#briefKept');if(!el)return;const kept=store.get('briefs.kept',[]);el.innerHTML=kept.length?`<h3 class="br-kh">Your briefs <span class="faint">kept on this device</span></h3><ul class="br-kept">${kept.map((k,i)=>`<li><button class="lk" data-brload="${i}">${esc(briefHead(k.b))}</button> <span class="faint">${fdate(k.at)}</span> <button class="lk faint" data-brdrop="${i}" aria-label="Forget this brief">×</button></li>`).join('')}</ul>`:'';}
function briefShow(){const o=$('#briefOut');if(!o)return;const m=briefCompose(briefs);o.innerHTML=renderMemo(m);store.set('brief.shown',true);scrollToEl(o);}
function briefClick(t){const d=t.dataset;
  if(d.copy==='letter'){const pre=t.closest('.br-letter').querySelector('pre');try{navigator.clipboard.writeText(pre.textContent);toast('Copied: paste it into your own mail');}catch(e){toast('Select the text and copy it');}return;}
  if(d.lot){const r=typeof lotByTitle==='function'?lotByTitle(d.lot):null;if(r)openLot(r);return;}
  if(d.artist){openArtist(d.artist);return;}
  if(d.tide&&window.__OCEAN){window.__OCEAN.open('tides',{id:d.tide});return;}
  if(d.reading&&window.__OCEAN){window.__OCEAN.open('tides',{reading:{sum:briefs.sum,years:briefs.years,risk:briefs.risk}});return;}
  if(d.nav&&window.__NAV){const p=briefPlan(briefs);window.__NAV.open({kind:briefs.kind,value:briefs.sum,year:briefs.year,from:p.J.from,to:p.J.to});return;}
  if(d.deal&&window.__DEAL){window.__DEAL.open({hammer:briefs.sum,room:brRoom(briefs.to||briefs.where)||'ny'});return;}
  if(d.trx&&window.__TR){window.__TR.open({sum:briefs.sum,from:brJ(briefs.where)||'us',back:'loan'});return;}
  if(d.book&&window.__OCEAN){window.__OCEAN.open('playbooks',{id:d.book});return;}
  if(d.walls){briefOpenWalls(d.walls);return;}
  if(d.case&&window.__OCEAN){window.__OCEAN.open('currents',{id:d.case});return;}
  if(d.player){worldJump({mode:'net',player:d.player});return;}
  if(d.event&&window.__SEASON){window.__SEASON.open(d.event);return;}
  if(d.whispers!=null&&window.__OCEAN){window.__OCEAN.open('whispers',{q:d.whispers});return;}
  if(d.wcase){briefOpenCase(d.wcase);return;}
  if(d.run){const c=brC().find(x=>x.id===d.run);if(c){Object.assign(briefs,briefFromCase(c));store.set('brief',briefs);go('brief');renderBrief();briefShow();}return;}
  if(d.source){briefOpenSources(d.source);return;}}
/* the worked cases: the research’s memos, on the same template, with a button that runs the live brief beside each */
function briefFromCase(c){const b={};const w=norm(c.persona||'');const who=BR_WHO.find(x=>w.includes(x[0]))||(/specialist|head of sale/.test(w)?['specialist']:/executor|heir|family in/.test(w)?['executor']:/owner|collector/.test(w)?['collector']:null);if(who)b.who=who[0];
  b.where=brCity(c.where||'');b.task=BR_TASK.some(t=>t[0]===c.kind)?c.kind:(/consign/.test(c.kind||'')?'sell':'buy');if(c.artist)b.artist=c.artist;if(c.category&&BR_CATS.includes(c.category))b.cat=c.category;
  const sum=typeof palSum==='function'?palSum(String(c.sum||'')):null;if(sum)b.sum=sum;const f=c.from||(c.road||[]).map(s=>s.who||'').join(' ');const fc=[...(typeof PAL_CITY_J==='object'?Object.keys(PAL_CITY_J):[])].sort((x,y)=>y.length-x.length).find(cc=>norm(c.task||'').includes(cc)&&norm(b.where)!==cc);if(fc)b.from=brCity(fc);else b.from=b.task==='buy'||b.task==='sell'?'New York':b.where;if(b.task==='buy'||b.task==='move')b.to=b.where;
  if(/sanction|designated|pep|politically/.test(norm(c.task+' '+(c.walls||[]).map(w=>w.n).join(' '))))b.party='exposed';return b;}
function renderCaseMemo(c){const sec=(n,html)=>html?`<section class="br-sec"><h4>${esc(n)}</h4>${html}</section>`:'';const srcOf=o=>(o&&o.src)||[];
  const road=(c.road||[]).length?`<ol class="br-steps">${c.road.map(s=>`<li><b>${esc(s.n)}</b>${s.who?` — ${esc(s.who)}`:''}${s.doc?` <span class="faint">${esc(s.doc)}</span>`:''}${s.time?` <span class="tag">${esc(s.time)}</span>`:''}${s.fee?` <span class="tag">${esc(s.fee)}</span>`:''}${s.vf?` <span class="tag flag">${esc(s.vf)}</span>`:''}${(s.src||[]).length?`<div class="src">${brSrcs(s.src,2)}</div>`:''}</li>`).join('')}</ol>`:'';
  const walls=(c.walls||[]).length?`<ul class="br-wl">${c.walls.map(w=>`<li><b>${esc(w.n)}</b>${w.cite?` <span class="faint">${esc(w.cite)}</span>`:''}${w.authority?` — ${esc(w.authority)}`:''}${w.threshold?`, ${esc(w.threshold)}`:''}${w.date?` (${esc(w.date)})`:''}: ${esc(w.what_it_does||'')}${w.case?` <span class="faint">${esc(w.case)}</span>`:''}${w.vf?` <span class="tag flag">${esc(w.vf)}</span>`:''}${(w.src||[]).length?`<div class="src">${brSrcs(w.src,2)}</div>`:''}</li>`).join('')}</ul>`:'';
  const risks=(c.risks||[]).length?`<ul class="br-risks">${c.risks.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>`:'';const next=(c.next||[]).length?`<ol class="br-next">${c.next.map(n=>`<li><label><input type="checkbox"> ${esc(n)}</label></li>`).join('')}</ol>`:'';
  const S=[...srcOf(c),...(c.road||[]).flatMap(s=>s.src||[]),...(c.walls||[]).flatMap(w=>w.src||[])];
  return `<article class="br-memo br-case" id="case-${esc(c.id)}" data-wcase="${esc(c.id)}"><header class="br-mh"><div class="br-mk">A worked case <span class="faint">${esc(c.persona||'')} · ${esc(c.where||'')}${c.kind?' · '+esc(c.kind):''}</span> ${c.vf?`<span class="tag flag">${esc(c.vf)}</span>`:''}</div><h3>${esc(c.task||'')}</h3>${c.sum?`<div class="faint">${esc(c.sum)}</div>`:''}</header>
   ${sec('The reading',c.reading?`<p>${esc(c.reading)}</p>`:'')}${sec('The money',c.money?`<p>${esc(c.money)}</p>`:'')}${sec('The road',road)}${sec('The walls',walls)}${sec('The people',c.people?`<p>${esc(c.people)}</p>`:'')}${sec('The calendar',c.calendar?`<p>${esc(c.calendar)}</p>`:'')}${sec('The whispers',c.whispers?`<p>${esc(c.whispers)}</p>`:'')}${sec('The risks',risks)}${sec('Value left on the table',c.value_left?`<p class="br-value">${esc(c.value_left)}</p>`:'')}${sec('Next',next)}
   <section class="br-sec br-srcs"><h4>Sources</h4><div class="src">${brSrcs(S,30)}</div>${c.note?`<p class="faint">${esc(c.note)}</p>`:''}<p class="faint"><button class="lk" data-run="${esc(c.id)}">Run this brief live</button> — the terminal’s own engines on the same task, today.</p></section></article>`;}
/* the specialist’s desk, as the record shows it: the roles, the season’s rhythm, the documents, the fees, the tools and where they failed */
function renderSpecialistDesk(){const D=(typeof CASES==='object'&&CASES&&CASES.desk)||{};if(!(D.roles||[]).length&&!D.day)return '';const li=(L,f)=>`<ul class="br-desk-l">${(L||[]).map(x=>`<li>${f(x)}${x.vf?` <span class="tag flag">${esc(x.vf)}</span>`:''}${(x.src||[]).length?`<div class="src">${brSrcs(x.src,2)}</div>`:''}</li>`).join('')}</ul>`;
  return `<details class="br-desk"><summary><b>The specialist’s desk</b> <span class="faint">as the record shows it: the roles, the season, the documents, the fees, the tools, the failures</span></summary>
   ${D.day?`<p class="br-desk-day">${esc(D.day)}</p>`:''}
   <div class="br-desk-g">${(D.roles||[]).length?`<section><h4>The roles</h4>${li(D.roles,x=>`<b>${esc(x.n)}</b> — ${esc(x.does||'')}`)}</section>`:''}${(D.rhythm||[]).length?`<section><h4>The season’s rhythm</h4>${li(D.rhythm,x=>`<b>${esc(x.n)}</b> — ${esc(x.when||'')}`)}</section>`:''}${(D.documents||[]).length?`<section><h4>The documents</h4>${li(D.documents,x=>`<b>${esc(x.n)}</b> — ${esc(x.what||'')}`)}</section>`:''}${(D.fees||[]).length?`<section><h4>The fees, as published</h4>${li(D.fees,x=>`<b>${esc(x.n)}</b> — ${esc(x.figure||'')}${x.date?` <span class="faint">(${esc(x.date)})</span>`:''}`)}</section>`:''}${(D.tools||[]).length?`<section><h4>The tools</h4>${li(D.tools,x=>`<b>${esc(x.n)}</b> — ${esc(x.what||'')}`)}</section>`:''}${(D.failures||[]).length?`<section><h4>Where the tools failed</h4>${li(D.failures,x=>`<b>${esc(x.n)}</b> — ${esc(x.what||'')}${x.case?` <span class="faint">${esc(x.case)}</span>`:''}`)}</section>`:''}</div></details>`;}
function renderCases(){const el=$('#v-cases');if(!el)return;const C=brC();const kinds=[...new Set(C.map(c=>c.kind).filter(Boolean))];const sel=store.get('cases.kind','all');
  el.innerHTML=`<h1 id="h-cases">Worked cases</h1><p class="lead">Real tasks, solved on the record: a specialist’s proposal, a guarantee, a compliance refusal, an unpaid lot, a title claim, a private sale, a cross-border consignment, an estate; a collector in Singapore buying in New York, a seller in Hong Kong, buyers in Dubai, Mumbai, Shanghai, Lagos and Berlin, a family in Connecticut, a divorce in London, a loan in Geneva, a museum loan from Paris, a seller in Tokyo. Every figure carries its source; every case ends with where the houses leave value on the table, and a button that runs the same brief on the terminal’s engines today.</p>
  ${renderSpecialistDesk()}
  <div class="oc-filters" role="group" aria-label="Filter"><button class="tag${sel==='all'?' on':''}" data-ckind="all">All ${C.length}</button>${kinds.map(k=>`<button class="tag${sel===k?' on':''}" data-ckind="${esc(k)}">${esc(k)} ${C.filter(c=>c.kind===k).length}</button>`).join('')}<input type="search" id="caseQ" placeholder="A city, an artist, a word" aria-label="Filter the cases"></div>
  <div class="br-cases">${C.length?C.map(renderCaseMemo).join(''):'<div class="empty">The worked cases arrive with the v28 research bundle.</div>'}</div>`;
  const filt=()=>{const k=store.get('cases.kind','all');const s=(($('#caseQ',el)||{}).value||'').trim().toLowerCase();$$('.br-case',el).forEach(c=>{const C1=brC().find(x=>x.id===c.dataset.wcase)||{};c.hidden=!((k==='all'||C1.kind===k)&&(!s||c.textContent.toLowerCase().includes(s)));});};
  $$('[data-ckind]',el).forEach(b=>b.addEventListener('click',()=>{store.set('cases.kind',b.dataset.ckind);$$('[data-ckind]',el).forEach(x=>x.classList.toggle('on',x===b));filt();}));const q=$('#caseQ',el);if(q)q.addEventListener('input',filt);filt();
  el.addEventListener('click',e=>{const t=e.target.closest('button');if(t&&!t.dataset.ckind)briefClick(t);});}
function briefOpenCase(id){go('cases');const c=$(`#case-${brQ(id)}`);if(c){c.hidden=false;scrollToEl(c);c.classList.add('lit');setTimeout(()=>c.classList.remove('lit'),1600);return true;}return false;}
/* the walls: the compliance files */
function renderWallFile(F,head){const walls=(F.walls||[]).length?`<ul class="br-wl">${F.walls.map(w=>`<li><b>${esc(w.n)}</b>${w.cite?` <span class="faint">${esc(w.cite)}</span>`:''}${w.authority?` — ${esc(w.authority)}`:''}${w.threshold?`, ${esc(w.threshold)}`:''}${w.date?` (${esc(w.date)})`:''}: ${esc(w.what_it_does||'')}${w.case?`<div class="faint">${esc(w.case)}</div>`:''}${w.vf?` <span class="tag flag">${esc(w.vf)}</span>`:''}${(w.src||[]).length?`<div class="src">${brSrcs(w.src,3)}</div>`:''}</li>`).join('')}</ul>`:'';
  const cases=(F.cases||[]).length?`<ul class="br-cases-l">${F.cases.map(c=>`<li><b>${esc(c.n)}</b>: ${esc(c.what||'')}${c.vf?` <span class="tag flag">${esc(c.vf)}</span>`:''}${(c.src||[]).length?`<div class="src">${brSrcs(c.src,2)}</div>`:''}</li>`).join('')}</ul>`:'';
  const lawful=(F.lawful||[]).length?`<ul class="br-lawful">${F.lawful.map(l=>`<li><b>${esc(l.who)}</b>: ${esc(l.course)}${(l.src||[]).length?`<div class="src">${brSrcs(l.src,2)}</div>`:''}</li>`).join('')}</ul>`:'';
  const ru=(F.russia_side||[]).length?`<section class="br-sec"><h4>The other side of the border</h4><ul class="br-wl">${F.russia_side.map(r=>`<li><b>${esc(r.n)}</b>: ${esc(r.what||'')}${(r.src||[]).length?`<div class="src">${brSrcs(r.src,2)}</div>`:''}</li>`).join('')}</ul></section>`:'';
  return `<article class="br-memo br-wall" id="wall-${esc(F.id||'kandinsky')}"><header class="br-mh"><div class="br-mk">A compliance file</div><h3>${esc(head||F.n||'')}</h3></header>${F.summary?`<section class="br-sec"><h4>In one minute</h4><p>${esc(F.summary)}</p></section>`:''}<section class="br-sec"><h4>The walls</h4>${walls||'<p class="faint">The file arrives with the v28 research bundle.</p>'}</section>${cases?`<section class="br-sec"><h4>The cases, as the record states them</h4>${cases}</section>`:''}${lawful?`<section class="br-sec"><h4>The lawful course</h4>${lawful}</section>`:''}${ru}<section class="br-sec br-srcs"><h4>Sources</h4><div class="src">${brSrcs([...(F.src||[]),...(F.walls||[]).flatMap(w=>w.src||[])],30)}</div><p class="faint">A reading, never a route: the file names every control and no way around one. Not legal advice.</p></section></article>`;}
function renderWalls(){const el=$('#v-walls');if(!el)return;const W=brW();const K=W.kandinsky;const files=W.files||[];
  el.innerHTML=`<h1 id="h-walls">The Walls</h1><p class="lead">What stops a task, stated as the law states it: the authority, the citation, the threshold, the date, the control that enforces it, the case where it caught someone, and the lawful course. The first file answers the hardest brief the terminal is given — a designated person who wants a Kandinsky bought in New York and taken to Moscow — with every wall it hits. Then the politically exposed buyer, the unknown principal, the provenance gap, the protected material, the tax wall and the national treasure; and the capital files — weak currency into art, art as collateral, barter and exchange, holding structures, the digital rails, the free ports — and Russia’s corridors since 2022, read from the partners’ customs books. Every file ends in a lawful course or in the record of what happened to those who took the other one.</p>
  <div class="oc-filters" role="group" aria-label="Files"><button class="tag on" data-wfile="kandinsky">The Kandinsky</button>${files.map(f=>`<button class="tag" data-wfile="${esc(f.id)}">${esc(String(f.n||f.id).split(':')[0])}</button>`).join('')}</div>
  <div class="br-walls">${K?renderWallFile(Object.assign({id:'kandinsky'},K),'A designated person wants a Kandinsky bought in New York and taken to Moscow'):'<div class="empty">The files arrive with the v28 research bundle.</div>'}${files.map(f=>renderWallFile(f)).join('')}</div>`;
  $$('[data-wfile]',el).forEach(b=>b.addEventListener('click',()=>{$$('[data-wfile]',el).forEach(x=>x.classList.toggle('on',x===b));const t=$(`#wall-${brQ(b.dataset.wfile)}`,el);if(t)scrollToEl(t);}));
  el.addEventListener('click',e=>{const t=e.target.closest('button');if(t&&!t.dataset.wfile)briefClick(t);});}
function briefOpenWalls(id){go('walls');const t=$(`#wall-${brQ(id||'kandinsky')}`);if(t){scrollToEl(t);t.classList.add('lit');setTimeout(()=>t.classList.remove('lit'),1600);return true;}return false;}
/* the sources: where information lives in the art market */
function renderSources(){const el=$('#v-sources');if(!el)return;const S=brS();const L=S.sources||[];const kinds=[...new Set(L.map(s=>s.kind).filter(Boolean))];const sel=store.get('sources.kind','all');
  const row=s=>`<article class="br-src" data-kind="${esc(s.kind||'')}" id="src-${esc(s.id||'')}"><h3>${s.url?`<a class="rlink" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.n)}</a>`:esc(s.n)} <span class="tag">${esc(s.kind||'')}</span>${s.vf?` <span class="tag flag">${esc(s.vf)}</span>`:''}</h3>${s.who?`<div class="faint">${esc(s.who)}${s.cadence?' · '+esc(s.cadence):''}</div>`:''}${s.good_for?`<p><b>Good for</b> ${esc(s.good_for)}</p>`:''}${s.price?`<p><b>Price</b> ${esc(s.price)}</p>`:''}${s.record?`<p><b>On record</b> ${esc(s.record)}</p>`:''}${s.how_to_read?`<p><b>How to read it</b> ${esc(s.how_to_read)}</p>`:''}${(s.src||[]).length?`<div class="src">${brSrcs(s.src,2)}</div>`:''}</article>`;
  el.innerHTML=`<h1 id="h-sources">Sources</h1><p class="lead">Where information lives in the art market, and how a desk reads it: the press and the newsletters, the journalists whose calls the terminal scores, the podcasts, the reports, the databases, the registries and the law, the fairs, the regional presses. Each with what it is good for, what it costs, what it never prints, and its record where the terminal can check one.</p>
  <div class="oc-filters" role="group" aria-label="Filter"><button class="tag${sel==='all'?' on':''}" data-skind="all">All ${L.length}</button>${kinds.map(k=>`<button class="tag${sel===k?' on':''}" data-skind="${esc(k)}">${esc(k)} ${L.filter(s=>s.kind===k).length}</button>`).join('')}<input type="search" id="srcQ" placeholder="A name, a subject" aria-label="Filter the sources"></div>
  ${(S.next||[]).length?`<section class="trt"><h3>The week ahead, as the houses state it</h3><ul class="br-cal">${S.next.map(n=>`<li><span class="tag">${esc(n.when)}</span> <b>${esc(n.what)}</b>${n.house?` <span class="faint">${esc(n.house)}</span>`:''}${n.lots?`<div class="faint">${esc(n.lots)}</div>`:''}${(n.src||[]).length?`<div class="src">${brSrcs(n.src,2)}</div>`:''}</li>`).join('')}</ul></section>`:''}
  <div class="br-sources">${L.length?L.map(row).join(''):'<div class="empty">The sources arrive with the v28 research bundle.</div>'}</div>`;
  const filt=()=>{const k=store.get('sources.kind','all');const s=(($('#srcQ',el)||{}).value||'').trim().toLowerCase();$$('.br-src',el).forEach(c=>{c.hidden=!((k==='all'||c.dataset.kind===k)&&(!s||c.textContent.toLowerCase().includes(s)));});};
  $$('[data-skind]',el).forEach(b=>b.addEventListener('click',()=>{store.set('sources.kind',b.dataset.skind);$$('[data-skind]',el).forEach(x=>x.classList.toggle('on',x===b));filt();}));const q=$('#srcQ',el);if(q)q.addEventListener('input',filt);filt();}
function briefOpenSources(q){go('sources');const el=$('#v-sources');const i=$('#srcQ',el);if(i){i.value=q||'';i.dispatchEvent(new Event('input'));}const b=$('[data-skind="all"]',el);if(b&&!b.classList.contains('on'))b.click();return true;}
/* open the Brief on a parsed sentence or a set of fields */
function briefOpen(f){if(f&&typeof f==='string'){const parsed=briefParse(f);f=Object.assign({from:'',to:'',artist:'',party:'clean',house:'',mats:[]},parsed.where?{where:parsed.where}:{},parsed);}if(f&&typeof f==='object')Object.assign(briefs,f);store.set('brief',briefs);go('brief');renderBrief();briefShow();return Object.assign({},briefs);}
window.__BRIEF={compose:b=>briefCompose(b),parse:briefParse,open:briefOpen,head:briefHead,cases:brC,walls:brW,sources:brS,openCase:briefOpenCase,openWalls:briefOpenWalls,openSources:briefOpenSources,state:()=>Object.assign({},briefs)};
